def mult_atv(v: list[float]) -> list[float]:
    """The product A^T v."""
    n: int = len(v)
    out: list[float] = []
    for i in range(n):
        acc: float = 0.0
        for j in range(n):
            acc += v[j] / (((i + j) * (i + j + 1)) // 2 + j + 1)
        out.append(acc)
    return out

